add_action( 'template_redirect', 'perfectpixel_disable_attachment_pages', 1 );
add_filter( 'attachment_link', 'perfectpixel_disable_attachment_pages_link', 20, 2 );

function perfectpixel_disable_attachment_pages() {
	if ( ! is_attachment() ) {
		return;
	}
	$parent = (int) wp_get_post_parent_id( get_queried_object_id() );
	if ( $parent && 'publish' === get_post_status( $parent ) ) {
		wp_safe_redirect( get_permalink( $parent ), 301 );
		exit;
	}
	global $wp_query;
	$wp_query->set_404();
	status_header( 404 );
	nocache_headers();
}

function perfectpixel_disable_attachment_pages_link( $link, $post_id ) {
	$file = wp_get_attachment_url( $post_id );
	return $file ? $file : $link;
}
